from pathlib import Path
import re
root=Path(__file__).resolve().parents[1]
def js(name):
 s=(root/'scripts'/name).read_text()
 s=re.sub(r'^import .*?;\n','',s,flags=re.M)
 return re.sub(r'\bexport (?=(?:const|class|function|async))','',s)
prelude='\n'.join(js(name) for name in ['core.js','icons.js'])+'\nconst e=escapeHTML;\n'+'\n'.join(js(name) for name in ['notifications.js','view.js'])
harness=(root/'docs/preview-harness.js').read_text();a,b=harness.split('// UI_CLASS_BOUNDARY')
code=prelude+'\n'+a+'\n'+js('ui.js')+'\n'+b
css=(root/'styles/bank.css').read_text()
html='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Banco de Mana · Prévia interativa</title><style>'''+css+'''
html,body{margin:0;min-height:100%;background:#080e12;color:#c4d9dc;font:13px "Segoe UI",sans-serif}body{padding:25px 25px 40px;background:radial-gradient(ellipse at 30% 0,#14293077,transparent 65%),#080e12}.demo-top{max-width:1060px;margin:auto auto 22px;display:flex;gap:20px;justify-content:space-between;align-items:center}.demo-top h1{font:500 18px Bahnschrift,"Segoe UI",sans-serif;margin:0 0 5px;color:#e4f2ef}.demo-top p{font-size:10px;margin:0;color:#79969c}.demo-controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.demo-controls button,.demo-controls select{font:10px "Segoe UI",sans-serif;padding:9px 11px;border:1px solid #2c4751;background:#12232a;color:#b1d1d4;cursor:pointer}.demo-controls label{font-size:10px;display:flex;gap:4px;align-items:center;color:#88a8ad}.demo-controls input{accent-color:#60f5c5}.demo-frame{height:900px;max-width:1060px;margin:0 auto;border:1px solid #314851;box-shadow:0 30px 100px #0007;transition:max-width .2s ease}.demo-frame.is-gm{max-width:1060px}.window-content{height:100%;container-type:inline-size}.demo-foot{max-width:1060px;margin:17px auto 0;display:flex;gap:30px;align-items:start;justify-content:space-between}.demo-foot p{font-size:10px;line-height:1.7;color:#6d8c93;max-width:410px;margin:0}#demo-chat{width:340px;max-height:180px;overflow:auto;scrollbar-width:thin}#demo-chat .mb-chat{margin-bottom:8px}.demo-chat-title{font:9px Consolas,monospace;letter-spacing:1.4px;color:#6f959e;margin-bottom:10px}.demo-empty-chat{color:#536f78;font-size:10px}.mb-bank{height:100%}@media(max-width:850px){body{padding:16px 12px}.demo-top{flex-wrap:wrap}.demo-frame{height:850px}.demo-foot{flex-wrap:wrap}}@media(prefers-reduced-motion:reduce){.demo-frame{transition:none}}
</style><body><header class="demo-top"><div><h1>Banco de Mana</h1><p>Prévia interativa · Dados de exemplo · App HoloSuite / Foundry 13</p></div><div class="demo-controls"><select id="demo-role" aria-label="Visualizar como"><option value="player">Visão do jogador</option><option value="gm">Visão do mestre</option></select><button id="demo-gain">Simular ganho +250</button><button id="demo-loss">Simular perda −250</button><label><input id="demo-reduced" type="checkbox">Menos movimento</label><button id="demo-reset">Restaurar</button></div></header><div id="demo-app" class="demo-frame mb-app"><div class="window-content"></div></div><footer class="demo-foot"><p>Abra a visão do mestre para adicionar ou remover mana, escolher a cor e a sequência do aviso. Os botões “Simular” demonstram uma movimentação do mestre enquanto você vê a reserva compartilhada. Esta prévia não altera dados do Foundry.</p><div><div class="demo-chat-title">CHAT DA CAMPANHA / EXEMPLO</div><div id="demo-chat"></div></div></footer><script type="module">'''+code.replace('</script>','<\\/script>')+'</script></body></html>'
output=root/'Banco-Mana-Preview.html';output.write_text(html);print(output)
